// Extract query, pubkey, eventId from webhook payload
const body = $input.first().json.body || $input.first().json;
return [
  {
    json: {
      query: body.query || body.content || '',
      pubkey: body.pubkey || '',
      eventId: body.eventId || ''
    }
  }
];

// Extract SQL from Gemini response
const geminiResponse = $input.first().json;
let sql = '';
try {
  const text = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || geminiResponse.text || '';
  // Look for SQL inside triple backticks
  const match = text.match(/```(?:sql)?\s*\n?([\s\S]*?)```/);
  if (match) {
    sql = match[1].trim();
  } else {
    // Fallback: if no code fences, use the whole response
    sql = text.trim();
  }
} catch (e) {
  sql = '';
}

if (!sql) {
  throw new Error('Gemini did not return valid SQL: ' + JSON.stringify(geminiResponse).slice(0, 500));
}

// Safety: replace backticks inside SQL to prevent injection
sql = sql.replace(/`/g, '');

return [{
  json: {
    sql: sql
  }
}];

// Format BigQuery result as a Nostr DM reply
const bqResult = $input.first().json;
const userPubkey = $items('Extract Fields')[0].json.pubkey;

let replyText = '';
try {
  if (bqResult.rows && bqResult.rows.length > 0) {
    const headers = bqResult.schema.fields.map(f => f.name);
    const rows = bqResult.rows.map(row => {
      const values = headers.map((h, i) => row.f[i].v);
      return headers.map((h, i) => `${h}: ${values[i]}`).join(', ');
    });
    replyText = rows.join('\n');
    if (replyText.length > 2000) {
      replyText = replyText.slice(0, 1900) + '\n... (result truncated)';
    }
  } else if (bqResult.totalRows === '0') {
    replyText = 'No rows returned.';
  } else {
    replyText = JSON.stringify(bqResult, null, 2).slice(0, 1500);
  }
} catch (e) {
  replyText = 'Error formatting result: ' + e.message;
}

return [{
  json: {
    content: `Query result:
${replyText}`,
    toPubkey: userPubkey
  }
}];
